pragma solidity ^0.8.0;

contract FixtureTxOriginAdmin {
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    function changeOwnerViaOrigin(address newOwner) external {
        require(tx.origin == owner, "origin");
        owner = newOwner;
    }
}

