// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract FixturePublicLifecycle {
    uint256 public status;
    uint256 public round;

    function settleRound() external {
        require(block.timestamp > 1 days, "early");
        status = 2;
        round += 1;
    }
}
